import { useId } from 'react'
import { Card } from '../../components/Card'
import { es } from '../../i18n/es'
import './CvCard.css'

/**
 * Place kept for "Llena tu perfil con tu CV". The CV reader is another slice (spec 009), so
 * today it is only an announcement: no upload, no button and nothing generated by AI.
 */
export function CvCard() {
  const titleId = useId()
  return (
    <Card as="section" className="cv-card" aria-labelledby={titleId}>
      <div className="cv-card__head">
        <h2 id={titleId} className="cv-card__title">
          {es.profile.cv.title}
        </h2>
        <span className="cv-card__soon">{es.profile.cv.soon}</span>
      </div>
      <p className="cv-card__body">{es.profile.cv.body}</p>
    </Card>
  )
}
